steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { teams(filter: {name: {eq: \"Web\"}}) { nodes { id name issues(filter: {title: {contains: \"Design system audit\"}}) { nodes { id title priority url subscribers { nodes { id name email } } } } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-web-1\", priority: 1) { success issue { id title priority url } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(input: {id: \"i-web-1\", priority: 1}) { success issue { id title priority url } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-web-1\", input: {priority: 1}) { success issue { id title priority url } } }"
  }'
